def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'
    start_r, start_c = start
    goal_r, goal_c = goal
    if not is_valid(start_r, start_c) or not is_valid(goal_r, goal_c):
        return []
    if start == goal:
        return [start]
    from collections import deque
    queue = deque()
    visited = set()
    previous = {}
    queue.append((start_r, start_c))
    visited.add((start_r, start_c))
    found = False
    while queue:
        current_r, current_c = queue.popleft()
        if current_r == goal_r and current_c == goal_c:
            found = True
            break
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = current_r + dr, current_c + dc
            if is_valid(nr, nc) and (nr, nc) not in visited:
                visited.add((nr, nc))
                previous[(nr, nc)] = (current_r, current_c)
                queue.append((nr, nc))
    if found:
        path = []
        current = (goal_r, goal_c)
        while current != (start_r, start_c):
            path.append(current)
            current = previous.get(current)
            if current is None:
                return []
        path.append((start_r, start_c))
        path.reverse()
        return path
    else:
        return []
