        return []

    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([start])
    visited = set([start])
    predecessors = {}
    found = False

    while queue:
        current = queue.popleft()
        for d in directions:
            new_row = current[0] + d[0]
            new_col = current[1] + d[1]
            new_pos = (new_row, new_col)
            if is_valid(new_pos) and grid[new_row][new_col] == '.':
